pragma solidity ^0.8.0;

// Import OpenZeppelin's ERC-20 interface


contract LeafToUSDTLending {
    // Token addresses
    IERC20 public leafToken; // LEAF token
    IERC20 public usdtToken; // USDT token

    // Exchange rate (1 LEAF = 1.05 USDT)
    uint256 public constant EXCHANGE_RATE = 105;
    uint256 public constant EXCHANGE_RATE_DENOMINATOR = 100;
    
    // Maximum collateral utilization ratio (80%)
    uint256 public constant MAX_COLLATERAL_RATIO = 80;

    // Mapping to track user balances
    mapping(address => uint256) public leafDeposits; // LEAF deposited by users
    mapping(address => uint256) public usdtBorrowed; // USDT borrowed by users

    // Events
    event Deposited(address indexed user, uint256 amount);
    event Borrowed(address indexed user, uint256 amount);
    event Repaid(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);
    event LiquidityAdded(address indexed provider, uint256 leafAmount, uint256 usdtAmount);

    // Constructor to initialize token addresses
    constructor(address _leafToken, address _usdtToken) {
        leafToken = IERC20(_leafToken);
        usdtToken = IERC20(_usdtToken);
    }

    // Helper function to calculate available collateral for withdrawal
    function getWithdrawableCollateral(address user) public view returns (uint256) {
        uint256 totalDeposit = leafDeposits[user];
        uint256 borrowedAmount = usdtBorrowed[user];
        
        // If no USDT is borrowed, allow full withdrawal
        if (borrowedAmount == 0) {
            return totalDeposit;
        }
        
        // Convert borrowed USDT to required LEAF collateral
        uint256 requiredCollateral = (borrowedAmount * EXCHANGE_RATE_DENOMINATOR) / EXCHANGE_RATE;
        
        // If required collateral is greater than or equal to total deposit, user cannot withdraw
        if (requiredCollateral >= totalDeposit) {
            return 0;
        }
        
        // Maximum withdrawal is 80% of deposited LEAF
        uint256 maxWithdrawal = (totalDeposit * MAX_COLLATERAL_RATIO) / 100;
        uint256 availableAfterBorrowing = totalDeposit - requiredCollateral;
        return availableAfterBorrowing < maxWithdrawal ? availableAfterBorrowing : maxWithdrawal;
    }

    // Add liquidity to the contract for both LEAF and USDT
    function addLiquidity(uint256 leafAmount, uint256 usdtAmount) external {
        require(leafAmount > 0 || usdtAmount > 0, "Amounts must be greater than 0");

        if (leafAmount > 0) {
            bool leafSuccess = leafToken.transferFrom(msg.sender, address(this), leafAmount);
            require(leafSuccess, "LEAF transfer failed");
        }

        if (usdtAmount > 0) {
            bool usdtSuccess = usdtToken.transferFrom(msg.sender, address(this), usdtAmount);
            require(usdtSuccess, "USDT transfer failed");
        }

        emit LiquidityAdded(msg.sender, leafAmount, usdtAmount);
    }

    // Deposit LEAF as collateral
    function depositLEAF(uint256 amount) external {
        require(amount > 0, "Amount must be greater than 0");
        bool success = leafToken.transferFrom(msg.sender, address(this), amount);
        require(success, "LEAF transfer failed");
        leafDeposits[msg.sender] += amount;
        emit Deposited(msg.sender, amount);
    }

    // Borrow USDT using deposited LEAF as collateral
    function borrowUSDT(uint256 amount) external {
        require(amount > 0, "Amount must be greater than 0");

        // Calculate maximum borrowable amount (80% of deposited LEAF converted to USDT)
        uint256 maxBorrowable = ((leafDeposits[msg.sender] * MAX_COLLATERAL_RATIO) / 100) * EXCHANGE_RATE / EXCHANGE_RATE_DENOMINATOR;
        require(usdtBorrowed[msg.sender] + amount <= maxBorrowable, "Exceeds maximum borrowable amount");

        uint256 contractUSDTBalance = usdtToken.balanceOf(address(this));
        require(contractUSDTBalance >= amount, "Insufficient USDT in contract");

        bool success = usdtToken.transfer(msg.sender, amount);
        require(success, "USDT transfer failed");

        usdtBorrowed[msg.sender] += amount;
        emit Borrowed(msg.sender, amount);
    }

    // Repay borrowed USDT
    function repayUSDT(uint256 amount) external {
        require(amount > 0, "Amount must be greater than 0");
        require(usdtBorrowed[msg.sender] >= amount, "Insufficient USDT borrowed");

        bool success = usdtToken.transferFrom(msg.sender, address(this), amount);
        require(success, "USDT transfer failed");

        usdtBorrowed[msg.sender] -= amount;
        emit Repaid(msg.sender, amount);
    }

    // Withdraw LEAF collateral
    function withdrawLEAF(uint256 amount) external {
        require(amount > 0, "Amount must be greater than 0");
        uint256 withdrawable = getWithdrawableCollateral(msg.sender);
        require(withdrawable >= amount, "Exceeds withdrawable amount");

        bool success = leafToken.transfer(msg.sender, amount);
        require(success, "LEAF transfer failed");

        leafDeposits[msg.sender] -= amount;
        emit Withdrawn(msg.sender, amount);
    }
}
